function verifyFormatter(p,actual,h,u,s1,merkle){
 const eq=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
 if(actual.truncated||actual.sha!==p.input_tree)throw Error("original tree");
 const leaves=actual.tree.filter(x=>x.type!=="tree");
 if(leaves.length!==4623||Object.keys(p.full_input_files).length!==4623||Object.keys(p.full_post_format_files).length!==4623)throw Error("source count");
 for(const x of leaves){const v=p.full_input_files[x.path];if(!v||v.mode!==x.mode||v.git_blob!==x.sha)throw Error("input leaf "+x.path);}
 const changed=[];
 for(const [path,v]of Object.entries(p.full_post_format_files)){const before=p.full_input_files[path];if(!before||v.mode!==before.mode)throw Error("path/mode changed");if(v.sha256!==before.sha256||v.git_blob!==before.git_blob||v.bytes!==before.bytes)changed.push(path);}
 if(!eq(changed.sort(),p.changed_paths.slice().sort()))throw Error("delta mismatch");
 const vectorSummaries=[];
 for(const [path,v]of Object.entries(p.files)){
  if(h(v.content)!==v.sha256||u(v.content).length!==v.bytes||s1(u("blob "+v.bytes+"\0").concat(u(v.content)))!==v.git_blob)throw Error("output hash "+path);
  const post=p.full_post_format_files[path];for(const k of ["bytes","sha256","git_blob","mode"])if(post[k]!==v[k])throw Error("post map "+k);
  const a=p.complete_scoped_source_evidence.inputs[path];if(h(a.before_content)!==a.before_sha256||u(a.before_content).length!==a.before_bytes||a.before_sha256!==p.full_input_files[path].sha256)throw Error("before bytes");
  const bridge=p.bridges.find(x=>x.path===path),full=a.strict_bridge;
  if(!bridge||bridge.passed!==true||bridge.before_sha256!==a.before_sha256||bridge.after_sha256!==v.sha256||!bridge.full_ast_equal_including_type_comments_and_type_ignore_line_fields||!bridge.canonical_tokens_equal||!bridge.comments_and_statement_token_anchors_equal||!bridge.within_500_physical_lines)throw Error("bridge "+path);
  for(const k of Object.keys(bridge).filter(k=>!["physical_lines","within_500_physical_lines"].includes(k)))if(!eq(bridge[k],full[k]))throw Error("common bridge field "+k);
  if(!eq(full.ordered_literal_values.before,full.ordered_literal_values.after)||!eq(full.tokens.before.canonical_tokens,full.tokens.after.canonical_tokens)||!eq(full.tokens.before.anchored_comments,full.tokens.after.anchored_comments))throw Error("actual full vectors");
  if(v.content.split("\n").length-(v.content.endsWith("\n")?1:0)!==bridge.physical_lines)throw Error("line count");
  vectorSummaries.push({path,literals:full.ordered_literal_values.before.length,canonical_tokens:full.tokens.before.canonical_tokens.length,anchored_comments:full.tokens.before.anchored_comments.length,full_vector_equality:true,physical_lines:bridge.physical_lines});
 }
 const inputTree=merkle(Object.entries(p.full_input_files).map(([path,v])=>({path,mode:v.mode,sha:v.git_blob})),s1,u);
 const postTree=merkle(Object.entries(p.full_post_format_files).map(([path,v])=>({path,mode:v.mode,sha:v.git_blob})),s1,u);
 if(inputTree!==p.input_tree||postTree!==p.post_format_tree)throw Error("Merkle");
 if(!eq(p.environment_before,p.environment_after)||p.environment_before.project_imports.length||p.environment_before.distributions.ruff!=="0.15.17")throw Error("environment");
 if(p.job_outcome.steps.length!==8)throw Error("commands");
 let logbytes=0;
 for(const step of p.job_outcome.steps){const l=p.complete_scoped_source_evidence.command_logs[step.name];if(!l||!l.available||h(l.content)!==l.sha256||u(l.content).length!==l.bytes||step.log_sha256!==l.sha256||step.log_bytes!==l.bytes||step.returncode!==0||step.timed_out||!step.passed||!step.group_cleanup.passed||!step.group_cleanup.no_live_members_in_original_group||step.group_cleanup.errors.length)throw Error("command "+step.name);logbytes+=l.bytes;}
 if(logbytes!==p.complete_scoped_source_evidence.command_log_bytes||!p.harvest_passed||!p.job_outcome.passed||!p.job_outcome.source_unchanged||p.qualification_complete!==false||p.complete_scoped_source_evidence.test_bodies_executed!==false||p.complete_scoped_source_evidence.operation_probe_executed!==false)throw Error("outcome");
 const proof=p.complete_scoped_source_evidence.source_contract;if(!proof.passed||proof.project_imports.length||proof.files.length!==2||proof.files.some(x=>!x.full_inverse_ast_equal||!x.full_inverse_bytes_equal)||!proof.caller.original_inline_fallback_ast_equal||!proof.caller.join_after_original_batch_callback)throw Error("source proof");
 return {source_leaves:leaves.length,untouched_leaves:leaves.length-changed.length,changed_paths:changed,input_tree:inputTree,post_format_tree:postTree,vector_summaries:vectorSummaries,command_log_bytes:logbytes};
}
